const item = $input.item.json;
const content = item.description || "";

// --- Task Link ---
const taskLinkMatch = content.match(/Task Link:\s*(https?:\/\/\S+)/);
const taskLink = taskLinkMatch ? taskLinkMatch[1].trim() : "";

// --- Main Description (text between Task Link block and Deliverables:) ---
const descMatch = content.match(/Task Link:.*?\n+([\s\S]*?)(?=Deliverables:)/);
const description = descMatch ? descMatch[1].trim() : "";

// --- Deliverables (comma-separated or newline-separated) ---
const deliverablesMatch = content.match(/Deliverables:\s*([\s\S]*?)(?=Notes:)/);
let deliverables = [];
if (deliverablesMatch) {
  const raw = deliverablesMatch[1].trim();
  deliverables = raw
    .split(/,|\n/)
    .map(d => d.trim())
    .filter(Boolean);
}

// --- Notes (newline-separated) ---
const notesMatch = content.match(/Notes:\s*([\s\S]*?)(?=Resources:)/);
let notes = "";
if (notesMatch) {
  notes = notesMatch[1]
    .trim()
    .split("\n")
    .map(n => n.trim())
    .filter(Boolean)
    .join("\n"); // <-- return as single string
}

// --- Resources (newline-separated) ---
const resourcesMatch = content.match(/Resources:\s*([\s\S]*)$/);
let resources = [];
if (resourcesMatch) {
  resources = resourcesMatch[1]
    .trim()
    .split("\n")
    .map(r => r.trim())
    .filter(Boolean);
}

return {
  task_id: item.id,
  task_name: item.name || "",
  clickup_task_link: `https://app.clickup.com/t/${item.id}`,
  task_link: taskLink,
  description: description,
  deliverables: deliverables,   // array
  notes: notes,                 // string
  resources: resources,         // array
  status: item.status?.status || "",
  assignees: (item.assignees || []).map(a => a.username),// array
  task: $input.item.json
};
